// Package core holds the shared Remix Lab contracts: error categories, roles,
// inert view records and the small read interfaces that blocks and adapters
// implement.
//
// Nothing in this package holds state. View records are plain values that
// never alias a block's internal storage, so returning them from a realm does
// not hand out mutation capability.
package core

import (
	"errors"
	"strings"
	"unicode/utf8"
)

// ViewSchemaVersion is the version of the view/action shapes defined here.
// Bump it whenever an exported view struct changes shape.
const ViewSchemaVersion = 1

// Error categories. Blocks wrap these so that clients can classify failures
// by prefix without parsing free-form text.
var (
	ErrUnauthorized  = errors.New("remix: unauthorized")
	ErrNotFound      = errors.New("remix: not found")
	ErrInvalidInput  = errors.New("remix: invalid input")
	ErrLimitExceeded = errors.New("remix: limit exceeded")
	ErrInvalidState  = errors.New("remix: invalid state")
	ErrConflict      = errors.New("remix: conflict")
)

// Errorf returns an error whose message starts with the category's message,
// e.g. "remix: invalid input: title is empty".
func Errorf(category error, detail string) error {
	return errors.New(category.Error() + ": " + detail)
}

// Is reports whether err belongs to category.
func Is(err, category error) bool {
	if err == nil || category == nil {
		return false
	}
	msg := err.Error()
	cat := category.Error()
	return msg == cat || strings.HasPrefix(msg, cat+": ")
}

// Role is an address's standing inside a membership set. Roles are ordered:
// a higher role satisfies any requirement for a lower one.
type Role int

const (
	RoleNone Role = iota
	RoleMember
	RoleReviewer
	RoleOwner
)

func (r Role) String() string {
	switch r {
	case RoleNone:
		return "none"
	case RoleMember:
		return "member"
	case RoleReviewer:
		return "reviewer"
	case RoleOwner:
		return "owner"
	}
	return "unknown"
}

// Valid reports whether r is one of the defined roles.
func (r Role) Valid() bool {
	return r >= RoleNone && r <= RoleOwner
}

// AtLeast reports whether r satisfies a requirement of min.
func (r Role) AtLeast(min Role) bool {
	return r >= min
}

// ParseRole converts the canonical role name to a Role.
func ParseRole(s string) (Role, error) {
	switch s {
	case "none":
		return RoleNone, nil
	case "member":
		return RoleMember, nil
	case "reviewer":
		return RoleReviewer, nil
	case "owner":
		return RoleOwner, nil
	}
	return RoleNone, Errorf(ErrInvalidInput, "unknown role")
}

// CheckText validates user-supplied text: valid UTF-8, between minBytes and
// maxBytes long, not blank when minBytes > 0, and free of control
// characters (other than newline when multiline is set) and of invisible or
// direction-changing format characters (see IsHiddenFormat). It does not
// escape; rendering is the render block's job.
func CheckText(field, s string, minBytes, maxBytes int, multiline bool) error {
	if len(s) < minBytes || (minBytes > 0 && strings.TrimSpace(s) == "") {
		if minBytes == 1 || len(s) >= minBytes {
			return Errorf(ErrInvalidInput, field+" is required")
		}
		return Errorf(ErrInvalidInput, field+" is too short")
	}
	if len(s) > maxBytes {
		return Errorf(ErrLimitExceeded, field+" is too long")
	}
	if !utf8.ValidString(s) {
		return Errorf(ErrInvalidInput, field+" is not valid UTF-8")
	}
	for _, r := range s {
		if r == '\n' && multiline {
			continue
		}
		if r < 0x20 || r == 0x7f || (r >= 0x80 && r < 0xa0) || r == 0x2028 || r == 0x2029 {
			return Errorf(ErrInvalidInput, field+" contains control characters")
		}
		if IsHiddenFormat(r) {
			return Errorf(ErrInvalidInput, field+" contains invisible or direction-changing characters")
		}
	}
	return nil
}

// IsHiddenFormat reports whether r is an invisible or direction-changing
// format character that could make text display differently from its
// content: soft hyphen, Arabic letter mark, Mongolian vowel separator,
// zero-width space, LRM/RLM, bidi embeddings, overrides and isolates,
// invisible operators, the byte order mark and interlinear annotations.
// ZWNJ and ZWJ (U+200C, U+200D) are allowed because several scripts and
// emoji sequences need them.
func IsHiddenFormat(r rune) bool {
	switch {
	case r == 0x00ad, r == 0x061c, r == 0x180e, r == 0x200b, r == 0x200e, r == 0x200f, r == 0xfeff:
		return true
	case r >= 0x202a && r <= 0x202e:
		return true
	case r >= 0x2060 && r <= 0x206f:
		return true
	case r >= 0xfff9 && r <= 0xfffb:
		return true
	}
	return false
}

package core

// MemberView is an inert membership record.
type MemberView struct {
	Address address
	Role    Role
}

// MembershipReader is the read side of a membership set, implemented by the
// membership block and by adapters to shared membership realms.
type MembershipReader interface {
	// RoleOf returns addr's role, RoleNone for non-members.
	RoleOf(addr address) Role
	// Size returns the number of members.
	Size() int
	// Snapshot returns every member whose role is at least minRole, in a
	// stable order. ok is false (and the slice nil) when more than max
	// members qualify, so callers never act on a truncated electorate.
	// A negative max or an invalid minRole also yields (nil, false).
	Snapshot(minRole Role, max int) (addrs []address, ok bool)
}

// AuthorizationPolicy decides whether an authenticated actor may perform a
// named operation. The actor must come from the realm's authenticated
// context, never from a caller-supplied argument.
type AuthorizationPolicy interface {
	Authorize(op string, actor address) error
}

// BallotStatus is the lifecycle stage of a ballot.
type BallotStatus int

const (
	BallotDraft BallotStatus = iota
	BallotOpen
	BallotFinalized
)

func (s BallotStatus) String() string {
	switch s {
	case BallotDraft:
		return "draft"
	case BallotOpen:
		return "open"
	case BallotFinalized:
		return "finalized"
	}
	return "unknown"
}

// BallotOutcome is the committed result of a finalized ballot.
type BallotOutcome int

const (
	OutcomePending BallotOutcome = iota
	OutcomeWinner
	OutcomeTie
	OutcomeNoQuorum
	OutcomeNoVotes
)

func (o BallotOutcome) String() string {
	switch o {
	case OutcomePending:
		return "pending"
	case OutcomeWinner:
		return "winner"
	case OutcomeTie:
		return "tie"
	case OutcomeNoQuorum:
		return "no-quorum"
	case OutcomeNoVotes:
		return "no-votes"
	}
	return "unknown"
}

// BallotView is an inert summary of a ballot and its current tally.
type BallotView struct {
	ID             uint64
	Title          string
	Options        []string
	Status         BallotStatus
	Public         bool  // anyone may vote; no electorate snapshot
	ElectorateSize int   // 0 for public ballots
	QuorumPercent  int   // of the captured electorate
	OpenedAt       int64 // unix seconds, 0 while draft
	Deadline       int64 // unix seconds, 0 while draft
	Counts         []int // per option, same order as Options
	Abstentions    int
	Turnout        int // ballots cast, including abstentions
	Outcome        BallotOutcome
	Winner         int // option index when Outcome == OutcomeWinner, else -1
}

// BallotReader is the read side of a ballot box.
type BallotReader interface {
	Ballot(id uint64) (BallotView, bool)
}

// SubmissionStatus is the review state of a form submission.
type SubmissionStatus int

const (
	SubmissionSubmitted SubmissionStatus = iota
	SubmissionAccepted
	SubmissionRejected
)

func (s SubmissionStatus) String() string {
	switch s {
	case SubmissionSubmitted:
		return "submitted"
	case SubmissionAccepted:
		return "accepted"
	case SubmissionRejected:
		return "rejected"
	}
	return "unknown"
}

// SubmissionView is an inert copy of a submission.
type SubmissionView struct {
	ID        uint64
	Submitter address
	Answers   []string // in form field order
	Status    SubmissionStatus
}

// SubmissionReader is the read side of a form.
type SubmissionReader interface {
	Submission(id uint64) (SubmissionView, bool)
	// Submissions pages through submissions, optionally filtered by status
	// (pass -1 for all), in submission order.
	Submissions(status int, offset, limit int) []SubmissionView
	Count() int
}

// AppDescriptor identifies how a realm was composed. Generated realms expose
// one so the Lab can show an app's ingredients from the chain itself.
type AppDescriptor struct {
	Recipe            string
	RecipeVersion     string
	Components        []string // "<component-id>@<catalog-version>"
	ConfigDigest      string
	ViewSchemaVersion int
	Bindings          []string // "<interface>=<pkgpath>"
}

// Package render is the Remix Lab rendering block: escaping for untrusted
// text, Markdown tables, paginated lists, route parsing and gnoweb
// transaction links.
//
// Every string that came from a user must pass through Text or Paragraph
// before it reaches Markdown. Escaped output cannot open links, images,
// HTML, headings, tables, code spans, bare URLs or @mentions. (gnoweb still
// links a bare g1 address; that target is a first-party user page.)
// Invisible and direction-changing format characters are dropped.
package render

import (
	"net/url"
	"strconv"
	"strings"
)

// Text escapes s for inline Markdown. Newlines and control characters become
// spaces, invisible and direction-changing format characters are dropped,
// every ASCII punctuation character Markdown or gnoweb could interpret is
// backslash-escaped, and "<", ">" and "&" become entities.
func Text(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch {
		case isHiddenFormat(r):
			// dropped
		case r == '<':
			sb.WriteString("&lt;")
		case r == '>':
			sb.WriteString("&gt;")
		case r == '&':
			sb.WriteString("&amp;")
		case r < 0x20 || r == 0x7f || (r >= 0x80 && r < 0xa0) || r == 0x2028 || r == 0x2029:
			sb.WriteByte(' ')
		case r < 0x80 && isMarkdownPunct(byte(r)):
			sb.WriteByte('\\')
			sb.WriteRune(r)
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

// Paragraph escapes multi-line text, keeping line breaks as hard breaks.
// Leading indentation is removed so no line becomes a code block.
func Paragraph(s string) string {
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		lines[i] = Text(strings.TrimLeft(l, " \t"))
	}
	return strings.Join(lines, "  \n")
}

// Code renders s as an inline code span that cannot be closed early. Control
// characters become spaces, format characters are dropped, and "|" becomes
// "¦" so the span is also safe inside a table cell.
func Code(s string) string {
	s = strings.Map(func(r rune) rune {
		switch {
		case r < 0x20 || r == 0x7f || (r >= 0x80 && r < 0xa0) || r == 0x2028 || r == 0x2029:
			return ' '
		case isHiddenFormat(r):
			return -1
		case r == '|':
			return '¦'
		}
		return r
	}, s)
	fence := "`"
	for strings.Contains(s, fence) {
		fence += "`"
	}
	return fence + " " + s + " " + fence
}

func isMarkdownPunct(c byte) bool {
	return strings.IndexByte("\\`*_{}[]()#+-.!|~:\"'=$%^/@", c) >= 0
}

// isHiddenFormat matches core.IsHiddenFormat: invisible or
// direction-changing format characters (ZWNJ and ZWJ are kept).
func isHiddenFormat(r rune) bool {
	switch {
	case r == 0x00ad, r == 0x061c, r == 0x180e, r == 0x200b, r == 0x200e, r == 0x200f, r == 0xfeff:
		return true
	case r >= 0x202a && r <= 0x202e:
		return true
	case r >= 0x2060 && r <= 0x206f:
		return true
	case r >= 0xfff9 && r <= 0xfffb:
		return true
	}
	return false
}

// Heading returns a Markdown heading with escaped text. level is clamped to
// 1..6.
func Heading(level int, text string) string {
	if level < 1 {
		level = 1
	}
	if level > 6 {
		level = 6
	}
	return strings.Repeat("#", level) + " " + Text(text) + "\n\n"
}

// Table renders a Markdown table. Headers are escaped with Text. Row cells
// are NOT escaped: build rows with Row (untrusted text) or TrustedRow
// (markup from Link, TxLink, Code). As a last line of defence every cell has
// line breaks replaced and unescaped "|" escaped, so a cell can never split
// the row or end the table. Rows shorter than the header are padded; longer
// rows are truncated.
func Table(headers []string, rows [][]string) string {
	if len(headers) == 0 {
		return ""
	}
	var sb strings.Builder
	sb.WriteString("|")
	for _, h := range headers {
		sb.WriteString(" " + Text(h) + " |")
	}
	sb.WriteString("\n|")
	for range headers {
		sb.WriteString(" --- |")
	}
	sb.WriteString("\n")
	for _, row := range rows {
		sb.WriteString("|")
		for i := range headers {
			cell := ""
			if i < len(row) {
				cell = tableCell(row[i])
			}
			sb.WriteString(" " + cell + " |")
		}
		sb.WriteString("\n")
	}
	return sb.String() + "\n"
}

// tableCell keeps a cell on one line and inside its column.
func tableCell(c string) string {
	var sb strings.Builder
	backslashes := 0
	for _, r := range c {
		switch {
		case r == '\n' || r == '\r' || r == 0x85 || r == 0x2028 || r == 0x2029:
			sb.WriteByte(' ')
		case r == '|' && backslashes%2 == 0:
			sb.WriteString("\\|")
		default:
			sb.WriteRune(r)
		}
		if r == '\\' {
			backslashes++
		} else {
			backslashes = 0
		}
	}
	return sb.String()
}

// TrustedRow marks a row whose cells were already built from escaped text
// and trusted markup (for example links from Link or TxLink). Use Row for
// untrusted cells.
func TrustedRow(cells ...string) []string { return cells }

// Row escapes every cell.
func Row(cells ...string) []string {
	out := make([]string, len(cells))
	for i, c := range cells {
		out[i] = Text(c)
	}
	return out
}

// Link renders a link with an escaped label to a realm-relative target,
// e.g. "/r/foo/bar:polls/3". External or scheme-bearing targets are refused
// and rendered as plain escaped text.
func Link(label, target string) string {
	if !isRelativeRealmTarget(target) {
		return Text(label)
	}
	return "[" + Text(label) + "](" + target + ")"
}

// RealmURL turns a package path into the realm-relative URL gnoweb serves,
// optionally with a render path: RealmURL("gno.land/r/a/b", "polls/1") ->
// "/r/a/b:polls/1".
func RealmURL(pkgPath, renderPath string) string {
	base, ok := relativeRealm(pkgPath)
	if !ok {
		return ""
	}
	if renderPath == "" {
		return base
	}
	return base + ":" + escapePath(renderPath)
}

// RealmQueryURL is RealmURL with query parameters: keys must be Go
// identifiers and values are URL-encoded, so any value (including "&", "="
// or "%") reaches Render intact through ParsePath. route itself must not
// contain "?". It returns "" on invalid input.
func RealmQueryURL(pkgPath, route string, kv ...string) string {
	if strings.IndexByte(route, '?') >= 0 || len(kv)%2 != 0 {
		return ""
	}
	u := RealmURL(pkgPath, route)
	if u == "" {
		return ""
	}
	if route == "" {
		u += ":"
	}
	for i := 0; i < len(kv); i += 2 {
		if !isIdent(kv[i]) {
			return ""
		}
		sep := "&"
		if i == 0 {
			sep = "?"
		}
		u += sep + kv[i] + "=" + url.QueryEscape(kv[i+1])
	}
	return u
}

// TxLink renders a gnoweb transaction link for fn on the realm at pkgPath
// with the given key/value arguments. Function and key names must be Go
// identifiers; values are URL-encoded. Invalid input renders the label as
// plain text so a bad link never reaches the page.
func TxLink(label, pkgPath, fn string, kv ...string) string {
	u := TxURL(pkgPath, fn, kv...)
	if u == "" {
		return Text(label)
	}
	return "[" + Text(label) + "](" + u + ")"
}

// TxURL builds the gnoweb "$help" URL used by TxLink, or "" when the input
// is invalid.
func TxURL(pkgPath, fn string, kv ...string) string {
	base, ok := relativeRealm(pkgPath)
	if !ok || !isIdent(fn) || len(kv)%2 != 0 {
		return ""
	}
	u := base + "$help&func=" + fn
	for i := 0; i < len(kv); i += 2 {
		if !isIdent(kv[i]) {
			return ""
		}
		u += "&" + kv[i] + "=" + url.QueryEscape(kv[i+1])
	}
	return u
}

// ParsePath splits a render path such as "polls/3?page=2" into its route
// segments and query values. Malformed queries yield empty values.
func ParsePath(path string) ([]string, url.Values) {
	route, rawQuery := path, ""
	if i := strings.IndexByte(path, '?'); i >= 0 {
		route, rawQuery = path[:i], path[i+1:]
	}
	var segs []string
	for _, s := range strings.Split(route, "/") {
		if s != "" {
			segs = append(segs, s)
		}
	}
	q, err := url.ParseQuery(rawQuery)
	if err != nil {
		q = url.Values{}
	}
	return segs, q
}

// Page reads a 1-based "page" query value, clamped to 1..maxPage (a maxPage
// below 1 counts as 1).
func Page(q url.Values, maxPage int) int {
	if maxPage < 1 {
		maxPage = 1
	}
	p, err := strconv.Atoi(q.Get("page"))
	if err != nil || p < 1 {
		return 1
	}
	if p > maxPage {
		return maxPage
	}
	return p
}

// PageCount returns the number of pages needed for total items.
func PageCount(total, pageSize int) int {
	if total <= 0 || pageSize <= 0 {
		return 1
	}
	return (total + pageSize - 1) / pageSize
}

// Pager renders previous/next links for a paginated route under pkgPath.
// page is clamped to 1..pages.
func Pager(pkgPath, route string, page, pages int) string {
	if pages <= 1 {
		return ""
	}
	if page < 1 {
		page = 1
	}
	if page > pages {
		page = pages
	}
	var parts []string
	if page > 1 {
		parts = append(parts, Link("← previous", RealmQueryURL(pkgPath, route, "page", strconv.Itoa(page-1))))
	}
	parts = append(parts, "page "+strconv.Itoa(page)+" of "+strconv.Itoa(pages))
	if page < pages {
		parts = append(parts, Link("next →", RealmQueryURL(pkgPath, route, "page", strconv.Itoa(page+1))))
	}
	return strings.Join(parts, " · ") + "\n\n"
}

// relativeRealm maps "gno.land/r/..." to "/r/...". Every path segment must
// be non-empty and use only lowercase letters, digits, "_" and "-".
func relativeRealm(pkgPath string) (string, bool) {
	const prefix = "gno.land/r/"
	if !strings.HasPrefix(pkgPath, prefix) || len(pkgPath) > 256 {
		return "", false
	}
	for _, seg := range strings.Split(pkgPath[len(prefix):], "/") {
		if seg == "" {
			return "", false
		}
		for _, c := range seg {
			lower := c >= 'a' && c <= 'z'
			digit := c >= '0' && c <= '9'
			if !(lower || digit || c == '_' || c == '-') {
				return "", false
			}
		}
	}
	return pkgPath[len("gno.land"):], true
}

func isRelativeRealmTarget(t string) bool {
	if !strings.HasPrefix(t, "/r/") && !strings.HasPrefix(t, "/p/") {
		return false
	}
	for _, c := range t {
		if c <= ' ' || c == '(' || c == ')' || c == '<' || c == '>' || c == '"' || c == '\\' || c == '`' {
			return false
		}
	}
	return !strings.Contains(t, "//")
}

// escapePath keeps a render path safe inside a Markdown link target.
func escapePath(p string) string {
	var sb strings.Builder
	for i := 0; i < len(p); i++ {
		c := p[i]
		safe := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
			strings.IndexByte("/-_.?=&:", c) >= 0
		if safe {
			sb.WriteByte(c)
		} else {
			sb.WriteString("%" + strings.ToUpper(strconv.FormatInt(int64(c)>>4, 16)) + strings.ToUpper(strconv.FormatInt(int64(c)&15, 16)))
		}
	}
	return sb.String()
}

func isIdent(s string) bool {
	if s == "" || len(s) > 64 {
		return false
	}
	for i, c := range s {
		letter := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
		digit := c >= '0' && c <= '9'
		if !(letter || (i > 0 && digit)) {
			return false
		}
	}
	return true
}

// Package membership is the Remix Lab membership block: an address-based
// member set with owner/reviewer/member roles, invitation or open joining,
// and bounded listing.
//
// A host realm constructs a *Set, keeps it in an unexported variable and
// authenticates every mutation before calling it. The Set enforces its own
// invariants (limits, last-owner protection, join rules) but not who may
// administer it: that is the host's policy decision. Never export the *Set
// or return it from a realm function; any holder of the pointer can call its
// mutating methods with the host's storage authority.
//
// Membership is address-based. One address is not one human.
package membership

import (
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/core/v1"
	"gno.land/p/nt/avl/v0"
)

// JoinMode controls how a non-member becomes a member through Join.
type JoinMode int

const (
	JoinInvitation JoinMode = iota // Join requires a pending invitation
	JoinOpen                       // anyone may Join
)

func (m JoinMode) String() string {
	if m == JoinOpen {
		return "open"
	}
	return "invitation"
}

// HardMaxMembers bounds MaxMembers regardless of configuration.
const HardMaxMembers = 1000

// Config is the block configuration, fixed at construction.
type Config struct {
	JoinMode   JoinMode
	MaxMembers int // includes owners and reviewers
}

// Validate checks configuration bounds.
func (c Config) Validate() error {
	if c.JoinMode != JoinInvitation && c.JoinMode != JoinOpen {
		return core.Errorf(core.ErrInvalidInput, "unknown join mode")
	}
	if c.MaxMembers < 1 || c.MaxMembers > HardMaxMembers {
		return core.Errorf(core.ErrInvalidInput, "maxMembers out of range")
	}
	return nil
}

// Set is a membership set. The zero value is not usable; call New.
type Set struct {
	cfg     Config
	members *avl.Tree // address string -> core.Role
	invites *avl.Tree // address string -> core.Role (role granted on Join)
	owners  int
}

// New creates a set whose first member is owner. It panics on invalid
// configuration or owner, since a host realm calls it from init.
func New(cfg Config, owner address) *Set {
	if err := cfg.Validate(); err != nil {
		panic(err.Error())
	}
	if !owner.IsValid() {
		panic(core.Errorf(core.ErrInvalidInput, "invalid owner address").Error())
	}
	s := &Set{cfg: cfg, members: avl.NewTree(), invites: avl.NewTree()}
	s.members.Set(owner.String(), core.RoleOwner)
	s.owners = 1
	return s
}

// Config returns the set's configuration.
func (s *Set) Config() Config { return s.cfg }

// RoleOf returns addr's role, RoleNone for non-members.
func (s *Set) RoleOf(addr address) core.Role {
	v := s.members.Get(addr.String())
	if v == nil {
		return core.RoleNone
	}
	return v.(core.Role)
}

// IsMember reports whether addr holds any role.
func (s *Set) IsMember(addr address) bool {
	return s.members.Has(addr.String())
}

// Size returns the number of members.
func (s *Set) Size() int { return s.members.Size() }

// Owners returns the number of owners.
func (s *Set) Owners() int { return s.owners }

// IsInvited reports whether addr holds a pending invitation.
func (s *Set) IsInvited(addr address) bool {
	return s.invites.Has(addr.String())
}

// PendingInvites returns the number of pending invitations.
func (s *Set) PendingInvites() int { return s.invites.Size() }

// InviteRole returns the role a pending invitation for addr grants.
func (s *Set) InviteRole(addr address) (core.Role, bool) {
	v := s.invites.Get(addr.String())
	if v == nil {
		return core.RoleNone, false
	}
	return v.(core.Role), true
}

// Invites returns up to limit pending invitations starting at offset,
// ordered by address, with the role each one grants.
func (s *Set) Invites(offset, limit int) []core.MemberView {
	var out []core.MemberView
	if offset < 0 || limit <= 0 {
		return out
	}
	s.invites.IterateByOffset(offset, limit, func(k string, v any) bool {
		out = append(out, core.MemberView{Address: address(k), Role: v.(core.Role)})
		return false
	})
	return out
}

// Snapshot implements core.MembershipReader. A negative max or an invalid
// minRole yields (nil, false).
func (s *Set) Snapshot(minRole core.Role, max int) ([]address, bool) {
	if max < 0 || !minRole.Valid() {
		return nil, false
	}
	var out []address
	ok := true
	s.members.Iterate("", "", func(k string, v any) bool {
		if v.(core.Role).AtLeast(minRole) {
			if len(out) == max {
				ok = false
				return true
			}
			out = append(out, address(k))
		}
		return false
	})
	if !ok {
		return nil, false
	}
	return out, true
}

// List returns up to limit members starting at offset, ordered by address.
func (s *Set) List(offset, limit int) []core.MemberView {
	var out []core.MemberView
	if offset < 0 || limit <= 0 {
		return out
	}
	s.members.IterateByOffset(offset, limit, func(k string, v any) bool {
		out = append(out, core.MemberView{Address: address(k), Role: v.(core.Role)})
		return false
	})
	return out
}

// Invite records a pending invitation granting role on Join. Only valid in
// invitation mode. Pending invitations count against MaxMembers so that
// accepting every invitation can never exceed the limit.
func (s *Set) Invite(addr address, role core.Role) error {
	if s.cfg.JoinMode != JoinInvitation {
		return core.Errorf(core.ErrInvalidState, "set uses open joining")
	}
	if err := checkGrantable(addr, role); err != nil {
		return err
	}
	if s.IsMember(addr) {
		return core.Errorf(core.ErrConflict, "already a member")
	}
	if s.IsInvited(addr) {
		return core.Errorf(core.ErrConflict, "already invited")
	}
	if err := s.checkCapacity(); err != nil {
		return err
	}
	s.invites.Set(addr.String(), role)
	return nil
}

// RevokeInvite removes a pending invitation.
func (s *Set) RevokeInvite(addr address) error {
	if _, removed := s.invites.Remove(addr.String()); !removed {
		return core.Errorf(core.ErrNotFound, "no pending invitation")
	}
	return nil
}

// Join adds actor as a member. actor must be the authenticated caller.
func (s *Set) Join(actor address) error {
	if s.IsMember(actor) {
		return core.Errorf(core.ErrConflict, "already a member")
	}
	role := core.RoleMember
	if s.cfg.JoinMode == JoinInvitation {
		v, removed := s.invites.Remove(actor.String())
		if !removed {
			return core.Errorf(core.ErrUnauthorized, "invitation required")
		}
		role = v.(core.Role)
	} else {
		if !actor.IsValid() {
			return core.Errorf(core.ErrInvalidInput, "invalid address")
		}
		if err := s.checkCapacity(); err != nil {
			return err
		}
	}
	s.members.Set(actor.String(), role)
	if role == core.RoleOwner {
		s.owners++
	}
	return nil
}

// Leave removes actor. actor must be the authenticated caller. The last
// owner cannot leave.
func (s *Set) Leave(actor address) error {
	return s.remove(actor)
}

// Add directly adds addr with role. The host must have authorized the actor.
func (s *Set) Add(addr address, role core.Role) error {
	if err := checkGrantable(addr, role); err != nil {
		return err
	}
	if s.IsMember(addr) {
		return core.Errorf(core.ErrConflict, "already a member")
	}
	// An invitation for the same address is superseded by the direct add.
	_, hadInvite := s.invites.Remove(addr.String())
	if !hadInvite {
		if err := s.checkCapacity(); err != nil {
			return err
		}
	}
	s.members.Set(addr.String(), role)
	if role == core.RoleOwner {
		s.owners++
	}
	return nil
}

// Remove removes addr. The host must have authorized the actor. The last
// owner cannot be removed.
func (s *Set) Remove(addr address) error {
	return s.remove(addr)
}

// SetRole changes an existing member's role. Demoting the last owner fails.
func (s *Set) SetRole(addr address, role core.Role) error {
	if err := checkGrantable(addr, role); err != nil {
		return err
	}
	cur := s.RoleOf(addr)
	if cur == core.RoleNone {
		return core.Errorf(core.ErrNotFound, "not a member")
	}
	if cur == role {
		return nil
	}
	if cur == core.RoleOwner && s.owners == 1 {
		return core.Errorf(core.ErrInvalidState, "cannot demote the last owner")
	}
	if cur == core.RoleOwner {
		s.owners--
	}
	if role == core.RoleOwner {
		s.owners++
	}
	s.members.Set(addr.String(), role)
	return nil
}

func (s *Set) remove(addr address) error {
	cur := s.RoleOf(addr)
	if cur == core.RoleNone {
		return core.Errorf(core.ErrNotFound, "not a member")
	}
	if cur == core.RoleOwner {
		if s.owners == 1 {
			return core.Errorf(core.ErrInvalidState, "cannot remove the last owner")
		}
		s.owners--
	}
	s.members.Remove(addr.String())
	return nil
}

func (s *Set) checkCapacity() error {
	if s.members.Size()+s.invites.Size() >= s.cfg.MaxMembers {
		return core.Errorf(core.ErrLimitExceeded, "membership is full")
	}
	return nil
}

func checkGrantable(addr address, role core.Role) error {
	if !addr.IsValid() {
		return core.Errorf(core.ErrInvalidInput, "invalid address")
	}
	if role == core.RoleNone || !role.Valid() {
		return core.Errorf(core.ErrInvalidInput, "invalid role")
	}
	return nil
}

// Package policies is the Remix Lab permission block. A Policy maps named
// operations to an eligibility rule evaluated against a membership reader.
//
// Each operation is defined once with a floor: the most permissive rule it
// may ever be set to. Administrative operations get a floor of RuleReviewer
// or RuleOwner, so reconfiguring a policy can never hand admin powers to
// ordinary members or the public.
//
// Operations with an owner floor (typically policy changes and owner
// appointment) can never be disabled: setting them to RuleNobody would lock
// the owners out permanently.
//
// Policy changes affect future operations only. Ballot eligibility follows
// the electorate frozen when the ballot opened, not the current policy.
package policies

import (
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/core/v1"
	"gno.land/p/nt/avl/v0"
)

// Rule is an eligibility requirement. Rules are ordered from most to least
// permissive.
type Rule int

const (
	RulePublic Rule = iota
	RuleMember
	RuleReviewer
	RuleOwner
	RuleNobody // operation disabled
)

func (r Rule) String() string {
	switch r {
	case RulePublic:
		return "public"
	case RuleMember:
		return "member"
	case RuleReviewer:
		return "reviewer"
	case RuleOwner:
		return "owner"
	case RuleNobody:
		return "nobody"
	}
	return "unknown"
}

// ParseRule converts the canonical rule name to a Rule.
func ParseRule(s string) (Rule, error) {
	for r := RulePublic; r <= RuleNobody; r++ {
		if r.String() == s {
			return r, nil
		}
	}
	return RuleNobody, core.Errorf(core.ErrInvalidInput, "unknown rule")
}

// MaxOperations bounds the number of operations one policy defines.
const MaxOperations = 64

type entry struct {
	rule  Rule
	floor Rule
}

// RuleView is an inert description of one operation's rule.
type RuleView struct {
	Op    string
	Rule  Rule
	Floor Rule
}

// Policy evaluates named operations. Hold it in an unexported host-realm
// variable; its Set method changes authorization.
type Policy struct {
	members core.MembershipReader
	ops     *avl.Tree // op -> *entry
}

// New creates a policy reading roles from members. members may be the
// host's own membership set or an adapter to a reviewed shared realm.
func New(members core.MembershipReader) *Policy {
	if members == nil {
		panic(core.Errorf(core.ErrInvalidInput, "nil membership reader").Error())
	}
	return &Policy{members: members, ops: avl.NewTree()}
}

// Define registers op with an initial rule and a floor. It panics on invalid
// input because host realms call it from init with constant arguments.
func (p *Policy) Define(op string, rule, floor Rule) {
	if err := checkOp(op); err != nil {
		panic(err.Error())
	}
	if !floor.valid() || !rule.valid() {
		panic(core.Errorf(core.ErrInvalidInput, "invalid rule").Error())
	}
	if rule < floor {
		panic(core.Errorf(core.ErrInvalidInput, op+": rule below floor").Error())
	}
	if floor >= RuleOwner && rule == RuleNobody {
		panic(core.Errorf(core.ErrInvalidInput, op+": cannot be disabled").Error())
	}
	if p.ops.Has(op) {
		panic(core.Errorf(core.ErrConflict, op+": already defined").Error())
	}
	if p.ops.Size() >= MaxOperations {
		panic(core.Errorf(core.ErrLimitExceeded, "too many operations").Error())
	}
	p.ops.Set(op, &entry{rule: rule, floor: floor})
}

// Set changes the rule for a defined op. The host must have authorized the
// actor (typically through a "policy.set" operation with an owner floor).
func (p *Policy) Set(op string, rule Rule) error {
	e := p.get(op)
	if e == nil {
		return core.Errorf(core.ErrNotFound, "unknown operation")
	}
	if !rule.valid() {
		return core.Errorf(core.ErrInvalidInput, "invalid rule")
	}
	if rule < e.floor {
		return core.Errorf(core.ErrInvalidInput, op+": rule below floor "+e.floor.String())
	}
	if e.floor >= RuleOwner && rule == RuleNobody {
		return core.Errorf(core.ErrInvalidInput, op+": cannot be disabled")
	}
	e.rule = rule
	return nil
}

// Rule returns the current rule for op.
func (p *Policy) Rule(op string) (Rule, bool) {
	e := p.get(op)
	if e == nil {
		return RuleNobody, false
	}
	return e.rule, true
}

// Authorize implements core.AuthorizationPolicy. Unknown operations are
// denied.
func (p *Policy) Authorize(op string, actor address) error {
	e := p.get(op)
	if e == nil {
		return core.Errorf(core.ErrUnauthorized, "unknown operation "+op)
	}
	if allowed(e.rule, p.members.RoleOf(actor)) {
		return nil
	}
	if e.rule == RuleNobody {
		return core.Errorf(core.ErrUnauthorized, op+" is disabled")
	}
	return core.Errorf(core.ErrUnauthorized, op+" requires "+e.rule.String())
}

// Allowed reports whether actor may perform op, without building an error.
func (p *Policy) Allowed(op string, actor address) bool {
	e := p.get(op)
	return e != nil && allowed(e.rule, p.members.RoleOf(actor))
}

// List returns every operation's rule, ordered by operation name.
func (p *Policy) List() []RuleView {
	var out []RuleView
	p.ops.Iterate("", "", func(k string, v any) bool {
		e := v.(*entry)
		out = append(out, RuleView{Op: k, Rule: e.rule, Floor: e.floor})
		return false
	})
	return out
}

func (p *Policy) get(op string) *entry {
	v := p.ops.Get(op)
	if v == nil {
		return nil
	}
	return v.(*entry)
}

// allowed treats a role outside the defined range as no role, so a faulty
// MembershipReader can never grant more than owner.
func allowed(rule Rule, role core.Role) bool {
	if !role.Valid() {
		return rule == RulePublic
	}
	switch rule {
	case RulePublic:
		return true
	case RuleMember:
		return role.AtLeast(core.RoleMember)
	case RuleReviewer:
		return role.AtLeast(core.RoleReviewer)
	case RuleOwner:
		return role.AtLeast(core.RoleOwner)
	}
	return false
}

func (r Rule) valid() bool { return r >= RulePublic && r <= RuleNobody }

// checkOp accepts lowercase dotted identifiers such as "poll.open": each
// dot- or underscore-separated part starts with a letter and continues with
// letters or digits.
func checkOp(op string) error {
	if len(op) == 0 || len(op) > 48 {
		return core.Errorf(core.ErrInvalidInput, "operation name length")
	}
	partStart := true
	for _, c := range op {
		lower := c >= 'a' && c <= 'z'
		digit := c >= '0' && c <= '9'
		switch {
		case c == '.' || c == '_':
			if partStart {
				return core.Errorf(core.ErrInvalidInput, "invalid operation name")
			}
			partStart = true
		case lower || (digit && !partStart):
			partStart = false
		default:
			return core.Errorf(core.ErrInvalidInput, "invalid operation name")
		}
	}
	if partStart {
		return core.Errorf(core.ErrInvalidInput, "invalid operation name")
	}
	return nil
}

// Package forms is the Remix Lab forms block: a fixed field schema, typed
// and bounded answers, sequential submission IDs and a small review status
// (submitted, accepted, rejected).
//
// All answers are public chain data. Recipes should only ask for information
// that is meant to be published.
//
// Capacity counts live submissions (submitted or accepted). Rejected
// submissions stay readable for the record but free their slot, so a flood
// of junk can always be cleared by reviewing it.
//
// The schema can change only while the form has no submissions; after that
// a host must create a new Form. A *Form belongs in an unexported host-realm
// variable, and the host authenticates submitters and reviewers.
package forms

import (
	"strconv"
	"strings"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/core/v1"
	"gno.land/p/nt/avl/v0"
)

// Hard bounds that no configuration may exceed.
const (
	HardMaxFields      = 10
	HardMaxSubmissions = 1000
	HardMaxFieldBytes  = 2048
	HardMaxPayload     = 8192
	HardMaxChoices     = 20
)

// FieldKind is the type of answer a field accepts.
type FieldKind int

const (
	KindText FieldKind = iota
	KindInteger
	KindChoice
)

func (k FieldKind) String() string {
	switch k {
	case KindText:
		return "text"
	case KindInteger:
		return "integer"
	case KindChoice:
		return "choice"
	}
	return "unknown"
}

// Field describes one form field.
type Field struct {
	Name      string // identifier, e.g. "title"
	Label     string
	Kind      FieldKind
	Required  bool
	MaxBytes  int      // text only
	Multiline bool     // text only
	Min, Max  int64    // integer only, inclusive
	Choices   []string // choice only
}

// Config bounds the form.
type Config struct {
	MaxSubmissions  int // live (submitted or accepted) submissions
	MaxPerSubmitter int // live submissions per address; 0 means unlimited
	MaxPayloadBytes int // sum of answer bytes
}

func (c Config) validate() error {
	switch {
	case c.MaxSubmissions < 1 || c.MaxSubmissions > HardMaxSubmissions:
		return core.Errorf(core.ErrInvalidInput, "maxSubmissions out of range")
	case c.MaxPerSubmitter < 0:
		return core.Errorf(core.ErrInvalidInput, "maxPerSubmitter out of range")
	case c.MaxPayloadBytes < 1 || c.MaxPayloadBytes > HardMaxPayload:
		return core.Errorf(core.ErrInvalidInput, "maxPayloadBytes out of range")
	}
	return nil
}

type submission struct {
	id        uint64
	submitter address
	answers   []string
	status    core.SubmissionStatus
}

// Form holds a schema and its submissions.
type Form struct {
	cfg          Config
	fields       []Field
	subs         *avl.Tree    // zero-padded id -> *submission
	byStatus     [3]*avl.Tree // per status: zero-padded id -> *submission
	perSubmitter *avl.Tree    // address -> live submission count
	nextID       uint64
}

// New creates a form. It panics on an invalid schema or configuration,
// since hosts call it from init with generated constants.
func New(cfg Config, fields []Field) *Form {
	if err := cfg.validate(); err != nil {
		panic(err.Error())
	}
	f := &Form{cfg: cfg, subs: avl.NewTree(), perSubmitter: avl.NewTree()}
	for i := range f.byStatus {
		f.byStatus[i] = avl.NewTree()
	}
	if err := f.setFields(fields); err != nil {
		panic(err.Error())
	}
	return f
}

// SetFields replaces the schema. It fails once any submission exists.
func (f *Form) SetFields(fields []Field) error {
	if f.subs.Size() > 0 {
		return core.Errorf(core.ErrInvalidState, "schema is frozen once submissions exist")
	}
	return f.setFields(fields)
}

func (f *Form) setFields(fields []Field) error {
	if len(fields) == 0 || len(fields) > HardMaxFields {
		return core.Errorf(core.ErrInvalidInput, "field count out of range")
	}
	names := map[string]bool{}
	out := make([]Field, len(fields))
	for i, fd := range fields {
		if err := checkField(fd); err != nil {
			return err
		}
		if names[fd.Name] {
			return core.Errorf(core.ErrInvalidInput, "duplicate field "+fd.Name)
		}
		names[fd.Name] = true
		out[i] = copyField(fd)
	}
	f.fields = out
	return nil
}

// Fields returns a copy of the schema.
func (f *Form) Fields() []Field {
	out := make([]Field, len(f.fields))
	for i, fd := range f.fields {
		out[i] = copyField(fd)
	}
	return out
}

// Normalize validates answers (one per field, in schema order) and returns
// their canonical form: integers are reformatted, and absent optional
// answers (including blank text) are "".
func (f *Form) Normalize(answers []string) ([]string, error) {
	if len(answers) != len(f.fields) {
		return nil, core.Errorf(core.ErrInvalidInput, "expected "+strconv.Itoa(len(f.fields))+" answers")
	}
	out := make([]string, len(answers))
	total := 0
	for i, fd := range f.fields {
		a := answers[i]
		total += len(a)
		if total > f.cfg.MaxPayloadBytes {
			return nil, core.Errorf(core.ErrLimitExceeded, "answers too large")
		}
		if a == "" || (fd.Kind == KindText && strings.TrimSpace(a) == "") {
			if fd.Required {
				return nil, core.Errorf(core.ErrInvalidInput, fd.Name+" is required")
			}
			continue
		}
		switch fd.Kind {
		case KindText:
			if err := core.CheckText(fd.Name, a, 1, fd.MaxBytes, fd.Multiline); err != nil {
				return nil, err
			}
			out[i] = a
		case KindInteger:
			if len(a) > 21 {
				return nil, core.Errorf(core.ErrInvalidInput, fd.Name+" must be an integer")
			}
			n, err := strconv.ParseInt(a, 10, 64)
			if err != nil {
				return nil, core.Errorf(core.ErrInvalidInput, fd.Name+" must be an integer")
			}
			if n < fd.Min || n > fd.Max {
				return nil, core.Errorf(core.ErrInvalidInput, fd.Name+" out of range")
			}
			out[i] = strconv.FormatInt(n, 10)
		case KindChoice:
			if !contains(fd.Choices, a) {
				return nil, core.Errorf(core.ErrInvalidInput, fd.Name+" is not an allowed choice")
			}
			out[i] = a
		}
	}
	return out, nil
}

// Submit stores a submission from submitter, who must be the authenticated
// caller.
func (f *Form) Submit(submitter address, answers []string) (uint64, error) {
	if !submitter.IsValid() {
		return 0, core.Errorf(core.ErrInvalidInput, "invalid submitter")
	}
	if f.live() >= f.cfg.MaxSubmissions {
		return 0, core.Errorf(core.ErrLimitExceeded, "form is full")
	}
	prev := f.submittedBy(submitter)
	if f.cfg.MaxPerSubmitter > 0 && prev >= f.cfg.MaxPerSubmitter {
		return 0, core.Errorf(core.ErrLimitExceeded, "submission limit reached for this address")
	}
	norm, err := f.Normalize(answers)
	if err != nil {
		return 0, err
	}
	f.nextID++
	id := f.nextID
	s := &submission{id: id, submitter: submitter, answers: norm, status: core.SubmissionSubmitted}
	f.subs.Set(key(id), s)
	f.byStatus[core.SubmissionSubmitted].Set(key(id), s)
	f.perSubmitter.Set(submitter.String(), prev+1)
	return id, nil
}

// Review moves a submitted entry to accepted or rejected. Decisions are
// final. Rejecting frees the entry's capacity slot and its submitter's
// per-address slot. The host must have authorized the reviewer.
func (f *Form) Review(id uint64, status core.SubmissionStatus) error {
	if status != core.SubmissionAccepted && status != core.SubmissionRejected {
		return core.Errorf(core.ErrInvalidInput, "review must accept or reject")
	}
	s := f.get(id)
	if s == nil {
		return core.Errorf(core.ErrNotFound, "submission")
	}
	if s.status != core.SubmissionSubmitted {
		return core.Errorf(core.ErrInvalidState, "submission already reviewed")
	}
	f.byStatus[s.status].Remove(key(id))
	s.status = status
	f.byStatus[status].Set(key(id), s)
	if status == core.SubmissionRejected {
		f.perSubmitter.Set(s.submitter.String(), f.submittedBy(s.submitter)-1)
	}
	return nil
}

// Submission implements core.SubmissionReader.
func (f *Form) Submission(id uint64) (core.SubmissionView, bool) {
	s := f.get(id)
	if s == nil {
		return core.SubmissionView{}, false
	}
	return s.view(), true
}

// Submissions implements core.SubmissionReader, ordered by ID. status -1
// returns all; any other value outside the defined statuses returns none.
// Each status has its own index, so paging never scans other entries.
func (f *Form) Submissions(status int, offset, limit int) []core.SubmissionView {
	var out []core.SubmissionView
	if offset < 0 || limit <= 0 || status >= len(f.byStatus) || status < -1 {
		return out
	}
	tree := f.subs
	if status >= 0 {
		tree = f.byStatus[status]
	}
	tree.IterateByOffset(offset, limit, func(_ string, v any) bool {
		out = append(out, v.(*submission).view())
		return false
	})
	return out
}

// Count implements core.SubmissionReader. It includes rejected entries.
func (f *Form) Count() int { return f.subs.Size() }

// CountByStatus returns the number of submissions in status.
func (f *Form) CountByStatus(status core.SubmissionStatus) int {
	if status < 0 || int(status) >= len(f.byStatus) {
		return 0
	}
	return f.byStatus[status].Size()
}

// Config returns the form configuration.
func (f *Form) Config() Config { return f.cfg }

// SubmittedBy returns how many live (submitted or accepted) submissions
// addr has.
func (f *Form) SubmittedBy(addr address) int { return f.submittedBy(addr) }

func (f *Form) live() int {
	return f.byStatus[core.SubmissionSubmitted].Size() + f.byStatus[core.SubmissionAccepted].Size()
}

func (f *Form) submittedBy(addr address) int {
	v := f.perSubmitter.Get(addr.String())
	if v == nil {
		return 0
	}
	return v.(int)
}

func (f *Form) get(id uint64) *submission {
	v := f.subs.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*submission)
}

func (s *submission) view() core.SubmissionView {
	answers := make([]string, len(s.answers))
	copy(answers, s.answers)
	return core.SubmissionView{ID: s.id, Submitter: s.submitter, Answers: answers, Status: s.status}
}

func checkField(fd Field) error {
	if !isFieldName(fd.Name) {
		return core.Errorf(core.ErrInvalidInput, "invalid field name")
	}
	if err := core.CheckText("label", fd.Label, 1, 80, false); err != nil {
		return err
	}
	// Attributes of other kinds must be left at their zero values.
	textAttrs := fd.MaxBytes != 0 || fd.Multiline
	intAttrs := fd.Min != 0 || fd.Max != 0
	choiceAttrs := fd.Choices != nil
	switch fd.Kind {
	case KindText:
		if intAttrs || choiceAttrs {
			return core.Errorf(core.ErrInvalidInput, fd.Name+": attributes do not match kind")
		}
		if fd.MaxBytes < 1 || fd.MaxBytes > HardMaxFieldBytes {
			return core.Errorf(core.ErrInvalidInput, fd.Name+": maxBytes out of range")
		}
	case KindInteger:
		if textAttrs || choiceAttrs {
			return core.Errorf(core.ErrInvalidInput, fd.Name+": attributes do not match kind")
		}
		if fd.Min > fd.Max {
			return core.Errorf(core.ErrInvalidInput, fd.Name+": min > max")
		}
	case KindChoice:
		if textAttrs || intAttrs {
			return core.Errorf(core.ErrInvalidInput, fd.Name+": attributes do not match kind")
		}
		if len(fd.Choices) < 2 || len(fd.Choices) > HardMaxChoices {
			return core.Errorf(core.ErrInvalidInput, fd.Name+": choice count out of range")
		}
		seen := map[string]bool{}
		for _, c := range fd.Choices {
			if err := core.CheckText("choice", c, 1, 80, false); err != nil {
				return err
			}
			if seen[c] {
				return core.Errorf(core.ErrInvalidInput, fd.Name+": duplicate choice")
			}
			seen[c] = true
		}
	default:
		return core.Errorf(core.ErrInvalidInput, fd.Name+": unknown kind")
	}
	return nil
}

func copyField(fd Field) Field {
	if fd.Choices != nil {
		c := make([]string, len(fd.Choices))
		copy(c, fd.Choices)
		fd.Choices = c
	}
	return fd
}

func isFieldName(s string) bool {
	if s == "" || len(s) > 32 {
		return false
	}
	for i, c := range s {
		if !((c >= 'a' && c <= 'z') || (i > 0 && ((c >= '0' && c <= '9') || c == '_'))) {
			return false
		}
	}
	return true
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func key(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 20 {
		s = "0" + s
	}
	return s
}

// Package ballots is the Remix Lab public-ballot block: single-choice polls
// with fixed options, an electorate captured at opening, one vote per
// eligible address, integer quorum and deterministic tie handling.
//
// Lifecycle: Create (draft) -> Open (options, rules and electorate freeze;
// the deadline starts) -> Finalize (any caller, once the deadline passed).
// A draft can be cancelled, which removes it. Early closure of an open
// ballot is not supported. Deadlines are only evaluated when a transaction
// or read happens; nothing closes a ballot automatically.
//
// MaxBallots bounds ballots that are not finalized (drafts and open
// ballots), so finalized history never blocks new ballots. Public ballots
// bound neither voters nor votes; each voter pays for their own vote's
// storage and nothing iterates over votes.
//
// Like every Remix Lab block, a *Box must stay in an unexported host-realm
// variable. The host authenticates callers and passes their address; the Box
// never trusts an address it did not receive from the host.
package ballots

import (
	"strconv"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/core/v1"
	"gno.land/p/nt/avl/v0"
)

// Hard bounds that no configuration may exceed.
const (
	HardMaxOptions    = 20
	HardMaxElectorate = 1000
	HardMaxBallots    = 1000
	HardMaxTextBytes  = 512
)

// Config is fixed at construction. Each ballot copies the rules it depends
// on when it is created, so they never change underneath an open ballot.
type Config struct {
	MaxBallots     int // drafts plus open ballots at any one time
	MaxOptions     int
	MaxElectorate  int
	QuorumPercent  int   // 0..100, of the captured electorate
	AllowAbstain   bool  // voters may cast an explicit abstention
	MinDuration    int64 // seconds
	MaxDuration    int64 // seconds
	MaxTitleBytes  int
	MaxOptionBytes int
}

// DefaultConfig returns the starting limits proposed for the MVP.
func DefaultConfig() Config {
	return Config{
		MaxBallots:     100,
		MaxOptions:     20,
		MaxElectorate:  100,
		QuorumPercent:  0,
		AllowAbstain:   false,
		MinDuration:    60,
		MaxDuration:    30 * 24 * 3600,
		MaxTitleBytes:  140,
		MaxOptionBytes: 80,
	}
}

// Validate checks configuration bounds.
func (c Config) Validate() error {
	switch {
	case c.MaxBallots < 1 || c.MaxBallots > HardMaxBallots:
		return core.Errorf(core.ErrInvalidInput, "maxBallots out of range")
	case c.MaxOptions < 2 || c.MaxOptions > HardMaxOptions:
		return core.Errorf(core.ErrInvalidInput, "maxOptions out of range")
	case c.MaxElectorate < 1 || c.MaxElectorate > HardMaxElectorate:
		return core.Errorf(core.ErrInvalidInput, "maxElectorate out of range")
	case c.QuorumPercent < 0 || c.QuorumPercent > 100:
		return core.Errorf(core.ErrInvalidInput, "quorumPercent out of range")
	case c.MinDuration < 1 || c.MaxDuration < c.MinDuration:
		return core.Errorf(core.ErrInvalidInput, "duration bounds")
	case c.MaxTitleBytes < 1 || c.MaxTitleBytes > HardMaxTextBytes:
		return core.Errorf(core.ErrInvalidInput, "maxTitleBytes out of range")
	case c.MaxOptionBytes < 1 || c.MaxOptionBytes > HardMaxTextBytes:
		return core.Errorf(core.ErrInvalidInput, "maxOptionBytes out of range")
	}
	return nil
}

// Abstain is the choice value for an abstention.
const Abstain = -1

type ballot struct {
	id           uint64
	creator      address
	title        string
	options      []string
	duration     int64
	quorum       int
	allowAbstain bool

	status     core.BallotStatus
	public     bool
	electorate *avl.Tree // address -> true; nil for public ballots
	openedAt   int64
	deadline   int64

	votes       *avl.Tree // address -> int choice
	counts      []int
	abstentions int

	outcome core.BallotOutcome
	winner  int
}

// Box holds a bounded set of ballots.
type Box struct {
	cfg     Config
	ballots *avl.Tree // zero-padded id -> *ballot
	nextID  uint64
	active  int // drafts plus open ballots
}

// NewBox creates an empty box. It panics on invalid configuration.
func NewBox(cfg Config) *Box {
	if err := cfg.Validate(); err != nil {
		panic(err.Error())
	}
	return &Box{cfg: cfg, ballots: avl.NewTree()}
}

// Config returns the box configuration.
func (b *Box) Config() Config { return b.cfg }

// Count returns the number of ballots, finalized ones included.
func (b *Box) Count() int { return b.ballots.Size() }

// Active returns the number of drafts and open ballots.
func (b *Box) Active() int { return b.active }

// Create adds a draft ballot. Options are copied. creator must be the
// authenticated caller.
func (b *Box) Create(creator address, title string, options []string, duration int64) (uint64, error) {
	if !creator.IsValid() {
		return 0, core.Errorf(core.ErrInvalidInput, "invalid creator")
	}
	if b.active >= b.cfg.MaxBallots {
		return 0, core.Errorf(core.ErrLimitExceeded, "too many active ballots")
	}
	if err := core.CheckText("title", title, 1, b.cfg.MaxTitleBytes, false); err != nil {
		return 0, err
	}
	if len(options) < 2 {
		return 0, core.Errorf(core.ErrInvalidInput, "at least two options required")
	}
	if len(options) > b.cfg.MaxOptions {
		return 0, core.Errorf(core.ErrLimitExceeded, "too many options")
	}
	opts := make([]string, len(options))
	seen := map[string]bool{}
	for i, o := range options {
		if err := core.CheckText("option", o, 1, b.cfg.MaxOptionBytes, false); err != nil {
			return 0, err
		}
		if seen[o] {
			return 0, core.Errorf(core.ErrInvalidInput, "duplicate option")
		}
		seen[o] = true
		opts[i] = o
	}
	if duration < b.cfg.MinDuration || duration > b.cfg.MaxDuration {
		return 0, core.Errorf(core.ErrInvalidInput, "duration out of range")
	}
	b.nextID++
	id := b.nextID
	b.ballots.Set(key(id), &ballot{
		id:           id,
		creator:      creator,
		title:        title,
		options:      opts,
		duration:     duration,
		quorum:       b.cfg.QuorumPercent,
		allowAbstain: b.cfg.AllowAbstain,
		status:       core.BallotDraft,
		counts:       make([]int, len(opts)),
		winner:       -1,
	})
	b.active++
	return id, nil
}

// CancelDraft removes a ballot that was never opened. The host must have
// authorized the actor.
func (b *Box) CancelDraft(id uint64) error {
	if _, err := b.draft(id); err != nil {
		return err
	}
	b.ballots.Remove(key(id))
	b.active--
	return nil
}

// Creator returns the address that created ballot id.
func (b *Box) Creator(id uint64) (address, bool) {
	bl := b.get(id)
	if bl == nil {
		return "", false
	}
	return bl.creator, true
}

// OpenWithElectorate opens a draft ballot restricted to voters. The list is
// copied; later membership changes do not affect this ballot.
func (b *Box) OpenWithElectorate(id uint64, now int64, voters []address) error {
	bl, err := b.draft(id)
	if err != nil {
		return err
	}
	if err := bl.checkOpenTime(now); err != nil {
		return err
	}
	if len(voters) == 0 {
		return core.Errorf(core.ErrInvalidInput, "empty electorate")
	}
	el := avl.NewTree()
	for _, v := range voters {
		if !v.IsValid() {
			return core.Errorf(core.ErrInvalidInput, "invalid voter address")
		}
		el.Set(v.String(), true)
		if el.Size() > b.cfg.MaxElectorate {
			return core.Errorf(core.ErrLimitExceeded, "electorate too large")
		}
	}
	bl.electorate = el
	bl.open(now)
	return nil
}

// OpenPublic opens a draft ballot to any address. Percentage quorum needs a
// known electorate, so public ballots require QuorumPercent == 0.
func (b *Box) OpenPublic(id uint64, now int64) error {
	bl, err := b.draft(id)
	if err != nil {
		return err
	}
	if bl.quorum != 0 {
		return core.Errorf(core.ErrInvalidState, "public ballots cannot use a percentage quorum")
	}
	if err := bl.checkOpenTime(now); err != nil {
		return err
	}
	bl.public = true
	bl.open(now)
	return nil
}

// Vote records voter's choice. voter must be the authenticated caller.
// Votes are final.
func (b *Box) Vote(id uint64, voter address, choice int, now int64) error {
	bl := b.get(id)
	if bl == nil {
		return core.Errorf(core.ErrNotFound, "ballot")
	}
	if bl.status != core.BallotOpen {
		return core.Errorf(core.ErrInvalidState, "ballot is not open")
	}
	if now >= bl.deadline {
		return core.Errorf(core.ErrInvalidState, "voting period has ended")
	}
	if !bl.eligible(voter) {
		return core.Errorf(core.ErrUnauthorized, "not in the electorate")
	}
	if bl.votes.Has(voter.String()) {
		return core.Errorf(core.ErrConflict, "already voted")
	}
	switch {
	case choice == Abstain && bl.allowAbstain:
		bl.abstentions++
	case choice >= 0 && choice < len(bl.options):
		bl.counts[choice]++
	default:
		return core.Errorf(core.ErrInvalidInput, "invalid choice")
	}
	bl.votes.Set(voter.String(), choice)
	return nil
}

// Finalize commits the result once the deadline has passed. Any caller may
// finalize; the outcome depends only on rules fixed at opening.
func (b *Box) Finalize(id uint64, now int64) (core.BallotView, error) {
	bl := b.get(id)
	if bl == nil {
		return core.BallotView{}, core.Errorf(core.ErrNotFound, "ballot")
	}
	if bl.status != core.BallotOpen {
		return core.BallotView{}, core.Errorf(core.ErrInvalidState, "ballot is not open")
	}
	if now < bl.deadline {
		return core.BallotView{}, core.Errorf(core.ErrInvalidState, "deadline not reached")
	}
	bl.outcome, bl.winner = bl.compute()
	bl.status = core.BallotFinalized
	b.active--
	return bl.view(), nil
}

// Ballot implements core.BallotReader.
func (b *Box) Ballot(id uint64) (core.BallotView, bool) {
	bl := b.get(id)
	if bl == nil {
		return core.BallotView{}, false
	}
	return bl.view(), true
}

// List returns up to limit ballots, newest first.
func (b *Box) List(offset, limit int) []core.BallotView {
	var out []core.BallotView
	if offset < 0 || limit <= 0 {
		return out
	}
	b.ballots.ReverseIterateByOffset(offset, limit, func(_ string, v any) bool {
		out = append(out, v.(*ballot).view())
		return false
	})
	return out
}

// HasVoted reports whether voter has cast a ballot (including abstention).
func (b *Box) HasVoted(id uint64, voter address) bool {
	bl := b.get(id)
	return bl != nil && bl.votes != nil && bl.votes.Has(voter.String())
}

// Eligible reports whether voter belongs to an open ballot's electorate. It
// ignores the deadline and whether voter has already voted.
func (b *Box) Eligible(id uint64, voter address) bool {
	bl := b.get(id)
	return bl != nil && bl.status == core.BallotOpen && bl.eligible(voter)
}

// InElectorate reports whether voter belongs to the ballot's frozen
// electorate (always true for public ballots once open).
func (b *Box) InElectorate(id uint64, voter address) bool {
	bl := b.get(id)
	return bl != nil && bl.status != core.BallotDraft && bl.eligible(voter)
}

func (b *Box) get(id uint64) *ballot {
	v := b.ballots.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*ballot)
}

func (b *Box) draft(id uint64) (*ballot, error) {
	bl := b.get(id)
	if bl == nil {
		return nil, core.Errorf(core.ErrNotFound, "ballot")
	}
	if bl.status != core.BallotDraft {
		return nil, core.Errorf(core.ErrInvalidState, "ballot already opened")
	}
	return bl, nil
}

// checkOpenTime rejects clocks that are unset or would overflow the
// deadline.
func (bl *ballot) checkOpenTime(now int64) error {
	const maxInt64 = int64(^uint64(0) >> 1)
	if now <= 0 || now > maxInt64-bl.duration {
		return core.Errorf(core.ErrInvalidInput, "invalid opening time")
	}
	return nil
}

func (bl *ballot) open(now int64) {
	bl.status = core.BallotOpen
	bl.openedAt = now
	bl.deadline = now + bl.duration
	bl.votes = avl.NewTree()
}

func (bl *ballot) eligible(voter address) bool {
	if bl.public {
		return voter.IsValid()
	}
	return bl.electorate != nil && bl.electorate.Has(voter.String())
}

func (bl *ballot) turnout() int {
	if bl.votes == nil {
		return 0
	}
	return bl.votes.Size()
}

func (bl *ballot) electorateSize() int {
	if bl.electorate == nil {
		return 0
	}
	return bl.electorate.Size()
}

// compute derives the outcome from the frozen rules and recorded votes.
// Integer arithmetic only: quorum is met when turnout*100 >= quorum*size.
func (bl *ballot) compute() (core.BallotOutcome, int) {
	turnout := bl.turnout()
	if turnout == 0 {
		return core.OutcomeNoVotes, -1
	}
	if !bl.public && turnout*100 < bl.quorum*bl.electorateSize() {
		return core.OutcomeNoQuorum, -1
	}
	best, bestCount, tie := -1, 0, false
	for i, c := range bl.counts {
		switch {
		case c > bestCount:
			best, bestCount, tie = i, c, false
		case c == bestCount && c > 0:
			tie = true
		}
	}
	if bestCount == 0 {
		return core.OutcomeNoVotes, -1
	}
	if tie {
		return core.OutcomeTie, -1
	}
	return core.OutcomeWinner, best
}

func (bl *ballot) view() core.BallotView {
	opts := make([]string, len(bl.options))
	copy(opts, bl.options)
	counts := make([]int, len(bl.counts))
	copy(counts, bl.counts)
	return core.BallotView{
		ID:             bl.id,
		Title:          bl.title,
		Options:        opts,
		Status:         bl.status,
		Public:         bl.public,
		ElectorateSize: bl.electorateSize(),
		QuorumPercent:  bl.quorum,
		OpenedAt:       bl.openedAt,
		Deadline:       bl.deadline,
		Counts:         counts,
		Abstentions:    bl.abstentions,
		Turnout:        bl.turnout(),
		Outcome:        bl.outcome,
		Winner:         bl.winner,
	}
}

func key(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 20 {
		s = "0" + s
	}
	return s
}

// Package clubpoll is a Remix Lab "club-poll" app generated from a
// project configuration. Members join by invitation; members vote in
// single-choice polls whose electorate is frozen when each poll opens.
//
// Authority model: every write derives the actor from cur.Previous(), the
// immediate caller. An intermediary realm calling on a user's behalf acts as
// itself and gains none of that user's roles. Block state lives in
// unexported variables and only inert views leave the realm.
package clubpoll

import (
	"strings"
	"time"

	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/ballots/v1"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/core/v1"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/membership/v1"
	"gno.land/p/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/policies/v1"
)

const (
	pkgPath       = "gno.land/r/g1lnkytfqcjwllws63gvf0mv9yt04aswy4y9amhm/remixlab/clubpoll"
	appTitle      = "Club poll"
	recipeID      = "club-poll"
	recipeVersion = "1.0.0"
	pageSize      = 25
	optionSep     = "|"
)

// Operation names checked against the policy.
const (
	opInvite  = "members.invite"
	opRemove  = "members.remove"
	opSetRole = "members.set_role"
	opCreate  = "poll.create"
	opOpen    = "poll.open"
	opPolicy  = "policy.set"
)

var (
	members *membership.Set
	policy  *policies.Policy
	polls   *ballots.Box
)

// init captures the deployer as the first owner. A realm whose deployer is
// not a user stays uninitialized and rejects every write; there is no
// separate initialization call that someone else could front-run.
func init(cur realm) {
	deployer := cur.Previous()
	if deployer.IsUser() && deployer.Address().IsValid() {
		setup(deployer.Address())
	}
}

func setup(owner address) {
	members = membership.New(membership.Config{
		JoinMode:   membership.JoinInvitation,
		MaxMembers: 100,
	}, owner)

	policy = policies.New(members)
	policy.Define(opInvite, policies.RuleOwner, policies.RuleReviewer)
	policy.Define(opRemove, policies.RuleOwner, policies.RuleOwner)
	policy.Define(opSetRole, policies.RuleOwner, policies.RuleOwner)
	policy.Define(opCreate, policies.RuleOwner, policies.RuleReviewer)
	policy.Define(opOpen, policies.RuleOwner, policies.RuleReviewer)
	policy.Define(opPolicy, policies.RuleOwner, policies.RuleOwner)

	polls = ballots.NewBox(ballots.Config{
		MaxBallots:     100,
		MaxOptions:     20,
		MaxElectorate:  100,
		QuorumPercent:  0,
		AllowAbstain:   false,
		MinDuration:    60,
		MaxDuration:    2592000,
		MaxTitleBytes:  140,
		MaxOptionBytes: 80,
	})
}

// --- Membership ---

// Invite lets addr join with role. Inviting a reviewer or owner also
// requires the members.set_role permission.
func Invite(cur realm, addr address, role string) {
	actor := authorize(cur, opInvite)
	r, err := core.ParseRole(role)
	must(err)
	if r > core.RoleMember {
		must(policy.Authorize(opSetRole, actor))
	}
	must(members.Invite(addr, r))
}

// RevokeInvite cancels a pending invitation. Revoking an invitation for a
// reviewer or owner also requires the members.set_role permission.
func RevokeInvite(cur realm, addr address) {
	actor := authorize(cur, opInvite)
	if r, ok := members.InviteRole(addr); ok && r > core.RoleMember {
		must(policy.Authorize(opSetRole, actor))
	}
	must(members.RevokeInvite(addr))
}

// Join accepts the caller's pending invitation.
func Join(cur realm) {
	ready()
	must(members.Join(cur.Previous().Address()))
}

// Leave removes the caller from the club. Open polls keep their frozen
// electorate.
func Leave(cur realm) {
	ready()
	must(members.Leave(cur.Previous().Address()))
}

// RemoveMember removes addr.
func RemoveMember(cur realm, addr address) {
	authorize(cur, opRemove)
	must(members.Remove(addr))
}

// SetRole changes addr's role.
func SetRole(cur realm, addr address, role string) {
	authorize(cur, opSetRole)
	r, err := core.ParseRole(role)
	must(err)
	must(members.SetRole(addr, r))
}

// --- Polls ---

// CreatePoll creates a draft poll. options are separated by "|".
func CreatePoll(cur realm, title string, options string, durationSeconds int64) uint64 {
	actor := authorize(cur, opCreate)
	id, err := polls.Create(actor, title, strings.Split(options, optionSep), durationSeconds)
	must(err)
	return id
}

// CancelPoll deletes a draft poll that was never opened, freeing its slot.
// The poll's creator may cancel it, and so may anyone allowed to open polls.
func CancelPoll(cur realm, id uint64) {
	ready()
	actor := cur.Previous().Address()
	if creator, ok := polls.Creator(id); ok && creator == actor {
		must(policy.Authorize(opCreate, actor))
	} else {
		must(policy.Authorize(opOpen, actor))
	}
	must(polls.CancelDraft(id))
}

// OpenPoll freezes the poll's options and captures the current members as
// its electorate.
func OpenPoll(cur realm, id uint64) {
	authorize(cur, opOpen)
	electorate, ok := members.Snapshot(core.RoleMember, polls.Config().MaxElectorate)
	if !ok {
		panic(core.Errorf(core.ErrLimitExceeded, "electorate too large").Error())
	}
	must(polls.OpenWithElectorate(id, time.Now().Unix(), electorate))
}

// Vote casts the caller's vote for option index choice.
func Vote(cur realm, id uint64, choice int) {
	ready()
	must(polls.Vote(id, cur.Previous().Address(), choice, time.Now().Unix()))
}

// Finalize commits a poll's result once its deadline has passed. Anyone may
// call it; the result depends only on rules frozen at opening.
func Finalize(cur realm, id uint64) {
	ready()
	_, err := polls.Finalize(id, time.Now().Unix())
	must(err)
}

// --- Policy ---

// SetRule changes the rule for an operation, within that operation's floor.
func SetRule(cur realm, op string, rule string) {
	authorize(cur, opPolicy)
	r, err := policies.ParseRule(rule)
	must(err)
	must(policy.Set(op, r))
}

// --- Reads ---

// Poll returns an inert summary of poll id.
func Poll(id uint64) (core.BallotView, bool) {
	ready()
	return polls.Ballot(id)
}

// Polls pages through polls, newest first.
func Polls(offset, limit int) []core.BallotView {
	ready()
	return polls.List(offset, clampLimit(limit))
}

// Members pages through members ordered by address.
func Members(offset, limit int) []core.MemberView {
	ready()
	return members.List(offset, clampLimit(limit))
}

// Invites returns up to limit pending invitations (at most 25) starting at
// offset, with the role each one grants.
func Invites(offset, limit int) []core.MemberView {
	ready()
	return members.Invites(offset, clampLimit(limit))
}

// RoleOf returns addr's role name.
func RoleOf(addr address) string {
	ready()
	return members.RoleOf(addr).String()
}

// HasVoted reports whether addr voted in poll id.
func HasVoted(id uint64, addr address) bool {
	ready()
	return polls.HasVoted(id, addr)
}

// Rules lists every operation's current rule.
func Rules() []policies.RuleView {
	ready()
	return policy.List()
}

// --- Internals ---

func authorize(cur realm, op string) address {
	ready()
	actor := cur.Previous().Address()
	must(policy.Authorize(op, actor))
	return actor
}

func ready() {
	if members == nil {
		panic(core.Errorf(core.ErrInvalidState, "app is not initialized").Error())
	}
}

func clampLimit(limit int) int {
	if limit < 1 || limit > pageSize {
		return pageSize
	}
	return limit
}

func must(err error) {
	if err != nil {
		panic(err.Error())
	}
}

